import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input_str = scanner.nextLine();
        StringBuilder intermediate = new StringBuilder();

        int index = 0;
        while (index < input_str.length()) {
            if (input_str.charAt(index) == 'd' && index + 2 < input_str.length()
                    && input_str.charAt(index + 1) == 'o' && input_str.charAt(index + 2) == 't') {
                intermediate.append('.');
                index += 3;
            } else if (input_str.charAt(index) == 'a' && index + 1 < input_str.length()
                    && input_str.charAt(index + 1) == 't') {
                intermediate.append('@');
                index += 2;
            } else {
                intermediate.append(input_str.charAt(index));
                index++;
            }
        }

        String intermediateStr = intermediate.toString();
        StringBuilder output_final = new StringBuilder();

        if (!intermediateStr.isEmpty()) {
            char firstChar = intermediateStr.charAt(0);
            if (firstChar == '.') {
                output_final.append("dot");
            } else if (firstChar == '@') {
                output_final.append("at");
            } else {
                output_final.append(firstChar);
            }

            int at_occurrence = 0;
            for (int m = 1; m + 1 < intermediateStr.length(); m++) {
                char currentChar = intermediateStr.charAt(m);
                if (currentChar == '@' && at_occurrence == 0) {
                    output_final.append(currentChar);
                    at_occurrence = 1;
                } else if (currentChar == '@' && at_occurrence == 1) {
                    output_final.append("at");
                } else {
                    output_final.append(currentChar);
                }
            }

            char lastChar = intermediateStr.charAt(intermediateStr.length() - 1);
            if (lastChar == '.') {
                output_final.append("dot");
            } else if (lastChar == '@') {
                output_final.append("at");
            } else {
                output_final.append(lastChar);
            }
        }

        System.out.println(output_final.toString());
        scanner.close();
    }
}
